/**
 * AETHER — default seeded question bank (statement + options; images rendered at seed time).
 *
 * 146 questions: aptitude 30 easy / 40 medium / 24 hard; technical 16 easy / 22 medium / 14 hard.
 * The medium bucket was expanded first (spec §2B) because that is the level that
 * ran short once the 30-day recent-question cooldown removed already-seen items.
 *
 * Seeding shuffles option order per question and recomputes the correct option, so
 * answer positions vary between databases.
 */

export interface SeedQuestion {
  id: string;
  roundType: 'aptitude' | 'technical';
  category: 'quantitative-aptitude' | 'logical-reasoning' | 'verbal-ability' | 'technical-quiz' | 'puzzle-solving';
  difficulty: 'easy' | 'medium' | 'hard';
  statement: string;
  options: [string, string, string, string];
  answer: string;
  explanation: string;
}

